B.YH=new A.q("You can greatly reduce your risk of malware by following a few simple cybersecurity habits.",null,null,null,null,null,null,null,null)
B.A1=new A.q("Best Practices",null,B.B,null,null,null,null,null,null)
B.ZU=new A.q("\u2022 Don\u2019t click suspicious links or attachments\n\u2022 Keep software and devices updated\n\u2022 Use strong, unique passwords\n\u2022 Enable two-factor authentication\n\u2022 Install trusted antivirus software\n\u2022 Avoid downloading from unknown sources",null,null,null,null,null,null,null,null)
B.zX=new A.q("Why This Matters",null,B.B,null,null,null,null,null,null)
B.Yr=new A.q("Most malware infections happen because of simple mistakes \u2014 clicking a fake link, downloading a bad file, or ignoring updates. Good habits protect you and everyone on your network.",null,null,null,null,null,null,null,null)
